import json
from collections import deque

with open('/home/ubuntu/runs/paper/qwen-hpl0-u1-turns/play/users/u000/system/state/workspace/programs/task-34f1d3f9.json', 'r') as f:
    demo_data = json.load(f)

inp = demo_data["input"]
out = demo_data["output"]
rows, cols = len(inp), len(inp[0])

# BFS from (0,0) through 4s only
# Each 4 gets a "distance" from (0,0) via 4-path
def bfs_dists(grid, start):
    dist = {start: 0}
    queue = deque([start])
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if (nr, nc) not in dist and grid[nr][nc] == 4:
                    dist[(nr, nc)] = dist[(r,c)] + 1
                    queue.append((nr, nc))
    return dist

bfs_dists_from_00 = bfs_dists(inp, (0,0))

# Check stay_4 vs become_3 by BFS distance
stay_4_by_dist = {}
become_3_by_dist = {}

for r in range(rows):
    for c in range(cols):
        if inp[r][c] == 4:
            d = bfs_dists_from_00.get((r,c), -1)
            if out[r][c] == 4:
                stay_4_by_dist[d] = stay_4_by_dist.get(d, 0) + 1
            else:
                become_3_by_dist[d] = become_3_by_dist.get(d, 0) + 1

print(f"Stay 4 by distance from (0,0): {sorted(stay_4_by_dist.items())}")
print(f"Become 3 by distance from (0,0): {sorted(become_3_by_dist.items())}")

